import re
import json
import sys

content = sys.stdin.read()

# Extract all step metrics
pattern = r'Step\s+(\d+)[^\n]*?loss[:\s]+([0-9.]+)[^\n]*?(?:f1_reward[:\s]+([0-9.]+))?[^\n]*?(?:format_reward[:\s]+([0-9.]+))?[^\n]*?(?:ced_reward[:\s]+([0-9.]+))?[^\n]*?(?:kl[:\s]+([0-9.eE\-+]+))?[^\n]*?(?:reward[:\s]+([0-9.]+))?'

lines = content.split('\n')
steps_data = {}

for i, line in enumerate(lines):
    # Look for step indicators
    if 'Step' in line and ('loss' in line or 'reward' in line or 'kl' in line):
        # Try to extract metrics
        step_match = re.search(r'Step\s+(\d+)', line)
        if step_match:
            step = step_match.group(1)
            metrics = {}

            # Extract metrics from this line and next few lines
            context = '\n'.join(lines[max(0, i-2):min(len(lines), i+5)])

            loss_m = re.search(r'loss[:\s=]+([0-9.]+)', context)
            if loss_m:
                metrics['loss'] = float(loss_m.group(1))

            f1_m = re.search(r'f1_reward[:\s=]+([0-9.]+)', context)
            if f1_m:
                metrics['f1_reward'] = float(f1_m.group(1))

            fmt_m = re.search(r'format_reward[:\s=]+([0-9.]+)', context)
            if fmt_m:
                metrics['format_reward'] = float(fmt_m.group(1))

            ced_m = re.search(r'ced_reward[:\s=]+([0-9.]+)', context)
            if ced_m:
                metrics['ced_reward'] = float(ced_m.group(1))

            kl_m = re.search(r'(?:kl|KL)[:\s=]+([0-9.eE\-+]+)', context)
            if kl_m:
                try:
                    metrics['kl'] = float(kl_m.group(1))
                except:
                    pass

            if metrics and step not in steps_data:
                steps_data[step] = metrics

# Print formatted
for step in sorted(steps_data.keys(), key=lambda x: int(x)):
